print("target tables present(expect 10):", [r[0] for r in tcur.fetchall()])
tcur.execute(
    "SELECT table_name, data_type FROM all_tab_columns WHERE owner='DBOPER' "
    "AND column_name='SYSTEM_TIME' AND table_name IN ("
    + ",".join(f"'{t}'" for t in TABLES) + ") ORDER BY table_name")
print("target SYSTEM_TIME types:", tcur.fetchall())
tcur.execute(
    "SELECT table_name, NUM_ROWS FROM all_tables WHERE owner='DBOPER' AND table_name IN ("
    + ",".join(f"'{t}'" for t in TABLES) + ") ORDER BY table_name")
print("target NUM_ROWS(stats):", tcur.fetchall())
tconn.close()

